import React,{useEffect,useMemo,useRef,useState}from'react';
import{
  Sparkles,Eye,EyeOff,Plus,Upload,WalletCards,Route,BarChart3,Target,
  ChevronLeft,ChevronRight,Check,Gift,Coins,Star,PiggyBank,Landmark,CreditCard,PieChart,
  ShieldCheck,Brain,ReceiptText,Layers3,HandCoins,TrendingUp,CircleDollarSign,X,Save,FileUp,
  ListChecks,ArrowUpRight,ArrowDownRight,LockKeyhole,FolderClock,Settings2
}from'lucide-react';
import'./Financeiro.css';
import{
  CATEGORIAS_DESPESA,CATEGORIAS_RECEITA,TIPOS_CONTA,TIPOS_INVESTIMENTO,TIPOS_DIVIDA,
  formatoMoeda,cloneFinanceiroInicial
}from'./financeiro.data.js';
import{
  normalizarFinanceiro,classificarTransacao,deduplicarTransacoes,resumoMes,categoriasMes,serieMeses,
  patrimonio,progressoObjetivo,reservaResumo,gastoCartao,orcamentoStatus,projecaoProximoMes,
  gerarMissoes,nivelFinanceiro,registrarAtividade,ofensivaStatus,insightsFinanceiros,parseCSV,
  mesHoje,rotuloMes,clamp,uid,hoje,impactos
}from'./financeiro.core.js';
import{parseTransacao,pedirSugestoes}from'./ia.jsx';
import FinanceiroStart from'./FinanceiroStart.jsx';
import{Wordmark}from'./ui.jsx';

const COLORS=['#3478F6','#8658E8','#F59E0B','#1EAD72','#EF5B5B','#7A8599','#29A6A6'];
const CRISTAIS_OFENSIVA={7:40,14:120,30:200,50:340};
const CurrencyContext=React.createContext('BRL');

const bytesBase64=file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onerror=()=>reject(new Error('Não consegui ler o arquivo.'));r.onload=()=>resolve(String(r.result||'').split(',')[1]||'');r.readAsDataURL(file)});
const dateBr=d=>d?new Date(`${d}T12:00:00`).toLocaleDateString('pt-BR'):'—';
const addMes=(mes,delta)=>{const[y,m]=mes.split('-').map(Number),dt=new Date(y,m-1+delta,1);return`${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}`};

function Money({value,hidden=false,className=''}){const moeda=React.useContext(CurrencyContext);return <span className={`${hidden?'fx2-hidden':''} ${className}`}>{formatoMoeda(value,moeda)}</span>}
function Progress({value,tone=''}){return <div className={`fx2-progress ${tone}`}><i style={{width:`${clamp(value)}%`}}/></div>}
function Section({title,action,onAction,children}){return <section className="fx2-section"><div className="fx2-section-head"><h3>{title}</h3>{action&&<button className="fx2-link" onClick={onAction}>{action}</button>}</div>{children}</section>}
function Empty({icon:Icon=CircleDollarSign,title,text,action,onAction}){return <div className="fx2-empty">{Icon&&<Icon size={29}/>}<b>{title}</b><small>{text}</small>{action&&<><div style={{height:10}}/><button className="fx2-btn ghost" onClick={onAction}>{action}</button></>}</div>}
function Back({onClick,label='Voltar'}){return <button className="fx2-back" onClick={onClick}><ChevronLeft size={15}/>{label}</button>}
function Field({label,children}){return <div className="fx2-field"><label>{label}</label>{children}</div>}
function Sheet({title,onClose,children}){return <div className="fx2-overlay" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="fx2-sheet"><div className="fx2-sheet-head"><h3>{title}</h3><button className="fx2-close" onClick={onClose}><X size={17}/></button></div>{children}</div></div>}

export default function Financeiro({d={},up=()=>{},aviso=()=>{}}){
  const fin=useMemo(()=>normalizarFinanceiro(d.financeiro),[d.financeiro]);
  const[tela,setTela]=useState('visao');
  const[mesRef,setMesRef]=useState(mesHoje());
  const[modal,setModal]=useState(null);
  const[importando,setImportando]=useState(false);
  const[importResult,setImportResult]=useState(null);
  const[contaImport,setContaImport]=useState('');
  const[iaTexto,setIaTexto]=useState('');
  const[iaLendo,setIaLendo]=useState(false);
  const[ofensivaDias,setOfensivaDias]=useState(30);
  const[investRange,setInvestRange]=useState(6);
  const[startUi,setStartUi]=useState({step:0,aberto:false});
  const inputFile=useRef(null);

  const persistir=fn=>up(s=>{const atual=normalizarFinanceiro(s.financeiro);const proximo=typeof fn==='function'?fn(atual):{...atual,...fn};return{...s,financeiro:proximo}});
  const agir=fn=>persistir(f=>registrarAtividade(typeof fn==='function'?fn(f):{...f,...fn}));

  useEffect(()=>{if(!d.financeiro||d.financeiro.versao!==2)up(s=>({...s,financeiro:cloneFinanceiroInicial()}))},[]);

  const resumo=useMemo(()=>resumoMes(fin,mesRef),[fin,mesRef]);
  const categorias=useMemo(()=>categoriasMes(fin,mesRef),[fin,mesRef]);
  const serie=useMemo(()=>serieMeses(fin,mesRef,6),[fin,mesRef]);
  const patri=useMemo(()=>patrimonio(fin),[fin]);
  const reserva=useMemo(()=>reservaResumo(fin),[fin]);
  const orcamentos=useMemo(()=>orcamentoStatus(fin,mesRef),[fin,mesRef]);
  const projecao=useMemo(()=>projecaoProximoMes(fin,mesRef),[fin,mesRef]);
  const missoes=useMemo(()=>gerarMissoes(fin,mesRef),[fin,mesRef]);
  const nivel=useMemo(()=>nivelFinanceiro(fin,mesRef),[fin,mesRef]);
  const ofensiva=useMemo(()=>ofensivaStatus(fin),[fin]);
  const insights=useMemo(()=>insightsFinanceiros(fin,mesRef),[fin,mesRef]);
  const hidden=!!fin.configuracao?.ocultarValores;
  const pendentes=fin.transacoes.filter(t=>t.revisar&&t.status!=='ignorado');
  const investimentosAtivos=useMemo(()=>fin.investimentos.filter(i=>i.ativo!==false),[fin.investimentos]);
  const reservaEmergencia=useMemo(()=>investimentosAtivos.filter(i=>String(i.tipo||'').toLowerCase()==='reserva').reduce((a,i)=>a+Number(i.valorAtual||0),0),[investimentosAtivos]);
  const aplicacoesTotal=useMemo(()=>investimentosAtivos.filter(i=>String(i.tipo||'').toLowerCase()!=='reserva').reduce((a,i)=>a+Number(i.valorAtual||0),0),[investimentosAtivos]);
  const totalInvestido=reservaEmergencia+aplicacoesTotal;
  const pctMetaInvest=fin.configuracao?.metaReserva>0?clamp(totalInvestido/Number(fin.configuracao.metaReserva)*100):0;

  const evolucaoInvestimentos=useMemo(()=>{
    const porMes={};
    investimentosAtivos.forEach(inv=>{
      const hist=Array.isArray(inv.historico)&&inv.historico.length?inv.historico:(inv.dataAtualizacao?[{data:inv.dataAtualizacao,valorAtual:Number(inv.valorAtual||0)}]:[]);
      hist.forEach(h=>{const mes=String(h.data||'').slice(0,7);if(!mes)return;(porMes[mes]??=[]).push({id:inv.id,valor:Number(h.valorAtual||0),data:h.data})});
    });
    const meses=Object.keys(porMes).sort();
    if(!meses.length)return[];
    return meses.map(mes=>{
      let total=0;
      investimentosAtivos.forEach(inv=>{
        const hist=(Array.isArray(inv.historico)&&inv.historico.length?inv.historico:(inv.dataAtualizacao?[{data:inv.dataAtualizacao,valorAtual:Number(inv.valorAtual||0)}]:[])).filter(h=>String(h.data||'').slice(0,7)<=mes).sort((a,b)=>String(a.data).localeCompare(String(b.data)));
        if(hist.length)total+=Number(hist[hist.length-1].valorAtual||0);
      });
      return{mes,total};
    });
  },[investimentosAtivos]);
  const evolucaoFiltrada=useMemo(()=>investRange===0?evolucaoInvestimentos:evolucaoInvestimentos.slice(-investRange),[evolucaoInvestimentos,investRange]);
  const maxInvest=Math.max(1,...evolucaoFiltrada.map(x=>x.total));
  const minInvest=evolucaoFiltrada.length?Math.min(...evolucaoFiltrada.map(x=>x.total)):0;
  const spreadInvest=Math.max(1,maxInvest-minInvest);
  const investPoints=evolucaoFiltrada.map((x,i)=>`${i*(100/Math.max(1,evolucaoFiltrada.length-1))},${90-((x.total-minInvest)/spreadInvest*72)}`).join(' ');
  const mesesEvolucao=new Set(evolucaoFiltrada.map(x=>x.mes));
  const aportesPeriodo=fin.transacoes.filter(t=>t.aporteInvestimento&&mesesEvolucao.has(String(t.data||'').slice(0,7))).reduce((a,t)=>a+Number(t.valor||0),0);
  const mediaAportes=evolucaoFiltrada.length?aportesPeriodo/evolucaoFiltrada.length:0;
  const variacaoInvest=evolucaoFiltrada.length>1?evolucaoFiltrada[evolucaoFiltrada.length-1].total-evolucaoFiltrada[0].total:0;

  useEffect(()=>{
    const premiadas=new Set(fin.gamificacao?.missoesPremiadas||[]),novas=missoes.filter(m=>m.concluida&&!premiadas.has(m.id));
    if(!novas.length&&Number(fin.gamificacao?.nivel||1)===nivel.nivel)return;
    persistir(f=>({...f,gamificacao:{...f.gamificacao,xp:Number(f.gamificacao.xp||0)+novas.reduce((a,m)=>a+m.xp,0),cristais:Number(f.gamificacao.cristais||0)+novas.reduce((a,m)=>a+m.cristais,0),nivel:nivel.nivel,missoesPremiadas:Array.from(new Set([...(f.gamificacao.missoesPremiadas||[]),...novas.map(m=>m.id)]))}}));
  },[missoes.map(m=>`${m.id}:${m.concluida}`).join('|'),nivel.nivel]);

  useEffect(()=>{
    if(!ofensiva?.concluida)return;
    const key=`ofensiva-${ofensiva.inicio}-${ofensiva.dias}`,abertos=fin.gamificacao?.bausAbertos||[];
    if(abertos.includes(key))return;
    setTela('bau');
  },[ofensiva?.concluida]);

  const abrir=(tipo,data={})=>setModal({tipo,data});
  const fechar=()=>setModal(null);
  const atualizarModal=(patch)=>setModal(m=>({...m,data:{...(m?.data||{}),...patch}}));
  const concluirOnboarding=()=>persistir(f=>({...f,onboardingConcluido:true}));

  const salvarTransacao=()=>{
    const m=modal?.data||{},v=Math.abs(Number(String(m.valor||'').replace(',','.'))||0);
    if(!v||!String(m.descricaoOriginal||'').trim())return aviso('Informe descrição e valor.');
    let tipo=m.tipo==='receita'?'receita':'despesa';const natureza=m.natureza||'normal';if(natureza==='resgate'||natureza==='estorno')tipo='receita';
    const tx=classificarTransacao({...m,id:uid('tx'),valor:v,valorMoedaBase:v,moeda:fin.configuracao?.moedaBase||'BRL',tipo,data:m.data||hoje(),origem:'manual',status:'confirmado',transferenciaInterna:natureza==='transferencia',pagamentoFatura:natureza==='fatura',aporteInvestimento:natureza==='aporte',resgateInvestimento:natureza==='resgate',estorno:natureza==='estorno'},fin.regrasClassificacao);
    agir(f=>({...f,onboardingConcluido:true,transacoes:[...f.transacoes,tx]}));setMesRef(tx.data.slice(0,7));fechar();aviso('Lançamento salvo');
  };

  const salvarConta=()=>{const m=modal?.data||{};if(!String(m.nome||'').trim())return aviso('Informe o nome da conta.');const saldoAtual=Number(String(m.saldoAtual||0).replace(',','.'))||0;const item={id:m.id||uid('conta'),nome:m.nome.trim(),instituicao:m.instituicao||'',tipo:m.tipo||'Conta corrente',saldoAtual,valorMoedaBase:saldoAtual,moeda:fin.configuracao?.moedaBase||'BRL',dataSaldo:m.dataSaldo||hoje(),disponibilidadeImediata:m.disponibilidadeImediata!==false,ativa:true};agir(f=>({...f,onboardingConcluido:true,contas:m.id?f.contas.map(x=>x.id===m.id?item:x):[...f.contas,item]}));fechar()};
  const salvarCartao=()=>{const m=modal?.data||{};if(!String(m.nome||'').trim())return aviso('Informe o nome do cartão.');const item={id:m.id||uid('card'),nome:m.nome.trim(),bandeira:m.bandeira||'',final:String(m.final||'').slice(-4),limiteTotal:Number(String(m.limiteTotal||0).replace(',','.'))||0,fechamento:Number(m.fechamento||0),vencimento:Number(m.vencimento||0),contaPagamentoId:m.contaPagamentoId||'',ativo:true};agir(f=>({...f,cartoes:m.id?f.cartoes.map(x=>x.id===m.id?item:x):[...f.cartoes,item]}));fechar()};
  const salvarInvestimento=()=>{const m=modal?.data||{};if(!String(m.nome||'').trim())return aviso('Informe o investimento.');const valorAtual=Number(String(m.valorAtual||0).replace(',','.'))||0,dataAtualizacao=m.dataAtualizacao||hoje(),anterior=fin.investimentos.find(x=>x.id===m.id),historico=[...(anterior?.historico||[])],ultimo=historico[historico.length-1];if(!ultimo||String(ultimo.data)!==dataAtualizacao||Number(ultimo.valorAtual)!==valorAtual)historico.push({data:dataAtualizacao,valorAtual});const item={id:m.id||uid('inv'),nome:m.nome.trim(),instituicao:m.instituicao||'',tipo:m.tipo||'Reserva',valorAplicado:Number(String(m.valorAplicado||0).replace(',','.'))||0,valorAtual,valorMoedaBase:valorAtual,moeda:fin.configuracao?.moedaBase||'BRL',liquidez:m.liquidez||'',dataAtualizacao,objetivoId:m.objetivoId||'',historico,ativo:true};agir(f=>({...f,investimentos:m.id?f.investimentos.map(x=>x.id===m.id?item:x):[...f.investimentos,item]}));fechar()};
  const salvarDivida=()=>{const m=modal?.data||{};if(!String(m.nome||'').trim())return aviso('Informe a dívida ou compromisso.');const saldo=Number(String(m.saldoDevedor||0).replace(',','.'))||0,parcela=Number(String(m.valorParcela||0).replace(',','.'))||0;const item={...(fin.dividas.find(x=>x.id===m.id)||{}),id:m.id||uid('div'),nome:m.nome.trim(),tipo:m.tipo||'Financiamento',valorOriginal:Number(String(m.valorOriginal||0).replace(',','.'))||0,saldoDevedor:saldo,saldoDevedorMoedaBase:saldo,valorParcela:parcela,valorParcelaMoedaBase:parcela,parcelasRestantes:Number(m.parcelasRestantes||0),taxa:Number(String(m.taxa||0).replace(',','.'))||0,vencimento:Number(m.vencimento||0),amortizacaoMensal:Number(String(m.amortizacaoMensal||0).replace(',','.'))||0,jurosMensal:Number(String(m.jurosMensal||0).replace(',','.'))||0,evolucaoObraMensal:Number(String(m.evolucaoObraMensal||0).replace(',','.'))||0,seguroMensal:Number(String(m.seguroMensal||0).replace(',','.'))||0,taxasMensais:Number(String(m.taxasMensais||0).replace(',','.'))||0,outrosNaoAmortizamMensal:Number(String(m.outrosNaoAmortizamMensal||0).replace(',','.'))||0,moeda:fin.configuracao?.moedaBase||'BRL',ativa:true};agir(f=>({...f,dividas:m.id?f.dividas.map(x=>x.id===m.id?item:x):[...f.dividas,item]}));fechar()};
  const salvarObjetivo=()=>{const m=modal?.data||{},alvo=Number(String(m.valorAlvo||0).replace(',','.'))||0;if(!String(m.nome||'').trim()||!alvo)return aviso('Informe nome e valor do objetivo.');const item={id:m.id||uid('obj'),nome:m.nome.trim(),valorAlvo:alvo,valorGuardado:Number(String(m.valorGuardado||0).replace(',','.'))||0,prazo:m.prazo||'',prioridade:m.prioridade||'Média',status:m.status||'ativo'};agir(f=>({...f,objetivos:m.id?f.objetivos.map(x=>x.id===m.id?item:x):[...f.objetivos,item]}));fechar()};
  const salvarOrcamento=()=>{const m=modal?.data||{},limite=Number(String(m.limite||0).replace(',','.'))||0;if(!limite)return aviso('Informe o limite.');const item={id:m.id||uid('orc'),categoria:m.categoria||'Total',limite,ativo:true};agir(f=>({...f,orcamentos:m.id?f.orcamentos.map(x=>x.id===m.id?item:x):[...f.orcamentos,item]}));fechar()};
  const salvarReserva=()=>{const m=modal?.data||{},meta=Number(String(m.metaReserva||0).replace(',','.'))||0;if(!meta)return aviso('Informe o valor da meta.');agir(f=>({...f,configuracao:{...f.configuracao,metaReserva:meta,prazoReserva:m.prazoReserva||'',aporteReservaMensal:Number(String(m.aporteReservaMensal||0).replace(',','.'))||0},metaAnual:{alvo:meta,ano:new Date().getFullYear()}}));fechar()};

  const revisarTx=()=>{const m=modal?.data||{},id=m.id;if(!id)return;agir(f=>{const regra=m.criarRegra&&m.termoRegra?.trim()?{id:uid('regra'),termo:m.termoRegra.trim(),categoria:m.categoria}:null;return{...f,regrasClassificacao:regra?[...f.regrasClassificacao,regra]:f.regrasClassificacao,transacoes:f.transacoes.map(x=>x.id===id?{...x,categoria:m.categoria||x.categoria,status:'confirmado',revisar:false,revisadoUsuario:true,confiancaClassificacao:1}:x)}});fechar();aviso('Classificação confirmada')};

  const importarArquivo=async file=>{
    if(!file)return;setImportando(true);setImportResult(null);
    try{
      let itens=[],perguntas=[];
      if(/\.csv$/i.test(file.name)||file.type==='text/csv')itens=parseCSV(await file.text(),{arquivo:file.name,contaId:contaImport,regras:fin.regrasClassificacao});
      else{const base64=await bytesBase64(file),r=await parseTransacao({imagemBase64:base64,mimeType:file.type||'application/pdf'});if(!r.ok)throw new Error(r.erro||'Não consegui ler o documento.');const dados=r.dados||{};perguntas=dados.perguntas||[];itens=(dados.transacoes||[]).map(t=>classificarTransacao({...t,contaId:contaImport,origem:'documento',origemArquivo:file.name,status:Number(t.confiancaClassificacao||0)<.62?'revisar':'confirmado'},fin.regrasClassificacao));}
      const{aceitas,duplicadas}=deduplicarTransacoes(fin.transacoes,itens);
      agir(f=>({...f,onboardingConcluido:true,transacoes:[...f.transacoes,...aceitas],importacoes:[...f.importacoes,{id:uid('imp'),arquivo:file.name,data:hoje(),lidas:itens.length,inseridas:aceitas.length,duplicadas:duplicadas.length}]}));
      setImportResult({arquivo:file.name,inseridas:aceitas.length,duplicadas:duplicadas.length,perguntas,revisar:aceitas.filter(t=>t.revisar).length});
    }catch(e){aviso(String(e.message||e))}finally{setImportando(false);if(inputFile.current)inputFile.current.value=''}
  };

  const iniciarOfensiva=()=>{agir(f=>({...f,gamificacao:{...f.gamificacao,ofensiva:{inicio:hoje(),dias:ofensivaDias,recompensa:CRISTAIS_OFENSIVA[ofensivaDias]},atividadeDias:Array.from(new Set([...(f.gamificacao.atividadeDias||[]),hoje()]))}}));setTela('trilha');aviso(`Ofensiva de ${ofensivaDias} dias iniciada`)};
  const abrirBau=()=>{if(!ofensiva?.concluida)return;const key=`ofensiva-${ofensiva.inicio}-${ofensiva.dias}`;persistir(f=>({...f,gamificacao:{...f.gamificacao,cristais:Number(f.gamificacao.cristais||0)+Number(ofensiva.recompensa||0),xp:Number(f.gamificacao.xp||0)+100,bausAbertos:Array.from(new Set([...(f.gamificacao.bausAbertos||[]),key])),ofensiva:null}}));setTela('trilha');aviso('Recompensa adicionada')};
  const pedirLeitura=async()=>{setIaLendo(true);const r=await pedirSugestoes({mes:mesRef,resumo:{receita:resumo.receita,despesa:resumo.despesa,resultado:resumo.resultado,categorias:categorias.slice(0,6),orcamentos,reserva:{meta:reserva.meta,atual:reserva.atual,pct:reserva.pct},projecao}});setIaLendo(false);if(r.ok)setIaTexto(r.dados?.texto||'');else aviso(r.erro||'Leitura indisponível')};

  const maxSerie=Math.max(1,...serie.flatMap(x=>[x.receita,x.despesa]));
  const points=key=>serie.map((x,i)=>`${i*(100/Math.max(1,serie.length-1))},${96-(x[key]/maxSerie*84)}`).join(' ');
  const donutParts=(()=>{let total=0;return categorias.slice(0,7).map((c,i)=>{const ini=total;total+=c.pct;return`${COLORS[i%COLORS.length]} ${ini}% ${total}%`}).join(',')})();

  const Header=()=> <div style={{display:'flex',alignItems:'center',padding:'2px 0 14px'}}><Wordmark altura={42} cor="#9B8DD3"/></div>;
  const Month=()=> <div className="fx2-month"><button onClick={()=>setMesRef(addMes(mesRef,-1))}><ChevronLeft size={15}/></button><span className="fx2-pill">{rotuloMes(mesRef)}</span><button onClick={()=>setMesRef(addMes(mesRef,1))}><ChevronRight size={15}/></button></div>;

  const Visao=()=> <>{!fin.startFinanceiroConcluido?<FinanceiroStart fin={fin} persistir={persistir} aviso={aviso} ui={startUi} setUi={setStartUi} onFinish={()=>setTela('visao')}/>:<><div className="fx2-hero"><div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',position:'relative',zIndex:1}}><div><h2>Painel financeiro</h2><p>Visão geral da sua vida financeira</p></div><button onClick={()=>persistir(f=>({...f,configuracao:{...f.configuracao,ocultarValores:!f.configuracao.ocultarValores}}))} style={{border:0,background:'transparent',color:'#fff'}}>{hidden?<EyeOff size={18}/>:<Eye size={18}/>}</button></div><div className="fx2-metrics"><div className="fx2-metric"><span>Receita</span><strong><Money value={resumo.receita} hidden={hidden}/></strong><small className="fx2-positive"><ArrowUpRight size={10}/> {resumo.itens.filter(t=>impactos(t).receita>0).length} entradas</small></div><div className="fx2-metric"><span>Despesas</span><strong><Money value={resumo.despesa} hidden={hidden}/></strong><small className="fx2-negative"><ArrowDownRight size={10}/> {resumo.itens.filter(t=>impactos(t).despesa>0).length} despesas</small></div><div className="fx2-metric"><span>Resultado do mês</span><strong><Money value={resumo.resultado} hidden={hidden}/></strong><small className={resumo.resultado>=0?'fx2-positive':'fx2-negative'}>{resumo.receita?`${Math.abs(resumo.resultado/resumo.receita*100).toFixed(0)}% da receita`:'Sem receita informada'}</small></div><div className="fx2-metric"><span>Saldo disponível</span><strong>{resumo.saldoDisponivel==null?'—':<Money value={resumo.saldoDisponivel} hidden={hidden}/>}</strong><small>{resumo.saldoDisponivel==null?'Informe o saldo das contas':`Atualizado ${resumo.dataSaldo?dateBr(resumo.dataSaldo):'manualmente'}`}</small></div></div></div><Month/><div className="fx2-quick"><button onClick={()=>abrir('transacao',{tipo:'despesa',natureza:'normal',data:hoje(),categoria:'Alimentação'})}><Plus size={18}/><span>Lançamento</span></button><button onClick={()=>setTela('importar')}><Upload size={18}/><span>Importar</span></button><button onClick={()=>setTela('reserva')}><PiggyBank size={18}/><span>Reserva</span></button><button onClick={()=>setTela('cartoes')}><CreditCard size={18}/><span>Cartões</span></button></div>{pendentes.length>0&&<div className="fx2-alert" style={{marginTop:13}} onClick={()=>setTela('revisoes')}><b>{pendentes.length} {pendentes.length===1?'item precisa':'itens precisam'} de revisão.</b> Confirme categorias antes de considerar a leitura final.</div>}<Section title="Resumo do mês" action="Ver detalhes" onAction={()=>setTela('painel')}><div className="fx2-card">{serie.some(x=>x.receita||x.despesa)?<><div className="fx2-chart"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><polyline fill="none" stroke="#31B65A" strokeWidth="2" vectorEffect="non-scaling-stroke" points={points('receita')}/><polyline fill="none" stroke="#EF5B5B" strokeWidth="2" vectorEffect="non-scaling-stroke" points={points('despesa')}/></svg></div><div className="fx2-legend"><span><i style={{background:'#31B65A'}}/>Receitas</span><span><i style={{background:'#EF5B5B'}}/>Despesas</span><span style={{marginLeft:'auto'}}>{serie.map(x=>x.label).join(' · ')}</span></div></>:<Empty icon={BarChart3} title="Ainda não há histórico" text="O gráfico aparece conforme você registra ou importa movimentações."/>}</div></Section><Section title="Reserva e futuro" action="Abrir" onAction={()=>setTela('reserva')}><div className="fx2-card"><div style={{display:'flex',justifyContent:'space-between',gap:10,alignItems:'center'}}><div><span className="fx2-muted">Reserva + aplicações</span><div className="fx2-bigmoney"><Money value={totalInvestido} hidden={hidden}/></div></div>{fin.configuracao?.metaReserva>0&&<span className="fx2-pill">{Math.round(pctMetaInvest)}% da meta</span>}</div>{fin.configuracao?.metaReserva>0?<><Progress value={pctMetaInvest}/><div style={{display:'flex',justifyContent:'space-between',marginTop:7}}><span className="fx2-muted">Meta <Money value={fin.configuracao.metaReserva} hidden={hidden}/></span><span className="fx2-muted">Faltam <Money value={Math.max(0,Number(fin.configuracao.metaReserva)-totalInvestido)} hidden={hidden}/></span></div></>:<button className="fx2-btn ghost" onClick={()=>abrir('reserva',{metaReserva:'',prazoReserva:'',aporteReservaMensal:''})}>Definir meta</button>}</div></Section><Section title="Leitura da NIIL" action="Atualizar" onAction={pedirLeitura}><div className="fx2-card">{insights.length||iaTexto?<>{insights.map((x,i)=><div className="fx2-insight" key={i}><Brain size={16} color="#8057E8"/><span>{x}</span></div>)}{iaTexto&&<div className="fx2-insight"><Sparkles size={16} color="#246BFD"/><span>{iaTexto}</span></div>}</>:<Empty icon={Brain} title="Ainda não há base suficiente" text="A NIIL só cria uma leitura quando existem dados reais para sustentar a análise."/>}{iaLendo&&<div className="fx2-muted">Analisando seus indicadores…</div>}</div></Section></>}</>;

  const Trilha=()=> <><div className="fx2-title"><h2>Minha trilha financeira</h2><p>As missões avançam pelos seus dados. Você não precisa marcar nada como concluído.</p></div>{ofensiva?<div className="fx2-card" style={{marginBottom:13}}><div style={{display:'flex',justifyContent:'space-between',alignItems:'center'}}><div><b style={{fontSize:11}}>Ofensiva de {ofensiva.dias} dias</b><div className="fx2-muted">{ofensiva.completos}/{ofensiva.dias} dias válidos</div></div><span className="fx2-pill">{Math.round(ofensiva.pct)}%</span></div><div style={{height:8}}/><Progress value={ofensiva.pct} tone="purple"/>{ofensiva.quebrada&&<div className="fx2-alert" style={{marginTop:9}}>A sequência foi interrompida. Você pode iniciar uma nova ofensiva quando quiser.</div>}</div>:<button className="fx2-btn wide" style={{marginBottom:13}} onClick={()=>setTela('ofensiva')}>COMEÇAR UMA OFENSIVA</button>}<div className="fx2-list">{missoes.map((m,i)=><div className={`fx2-mission ${m.concluida?'done':''}`} key={m.id}><div className={`fx2-dot ${m.concluida?'done':''}`}>{m.concluida?<Check size={13}/>:i+1}</div><div className="fx2-mission-card"><div className="fx2-row-icon">{m.id==='reserva'?<PiggyBank size={18}/>:m.id==='objetivo'?<Target size={18}/>:m.id==='orcamento'?<Layers3 size={18}/>:<ReceiptText size={18}/>}</div><div style={{flex:1}}><b>{m.titulo}</b><Progress value={m.pct}/><small>{Math.min(m.atual,m.meta)} / {m.meta} · +{m.xp} XP</small></div></div></div>)}</div><div className="fx2-level"><div style={{display:'flex',justifyContent:'space-between',alignItems:'center'}}><div><b style={{fontSize:11}}>Nível {nivel.nivel} · {nivel.nome}</b><div className="fx2-muted">{fin.gamificacao.xp||0} XP · {fin.gamificacao.cristais||0} cristais</div></div><Gift size={31} color="#B87824"/></div></div></>;
  const Ofensiva=()=> <><Back onClick={()=>setTela('trilha')}/><div className="fx2-title"><div className="fx2-brandmark" style={{margin:'0 auto 13px',width:66,height:66,borderRadius:22}}><Route size={29}/></div><h2>Escolha sua ofensiva</h2><p>Um dia só conta quando você registra, importa, revisa ou toma uma ação financeira real.</p></div><div className="fx2-options">{[7,14,30,50].map(x=><button key={x} className={`fx2-option ${ofensivaDias===x?'active':''}`} onClick={()=>setOfensivaDias(x)}><b>{x} dias</b><small>Ganhe {CRISTAIS_OFENSIVA[x]} cristais</small></button>)}</div><div style={{height:13}}/><button className="fx2-btn wide" onClick={iniciarOfensiva}>VOU ME DEDICAR</button></>;
  const Bau=()=> <><Back onClick={()=>setTela('trilha')}/><div className="fx2-title"><span className="fx2-pill">Nível {nivel.nivel}</span><h2 style={{marginTop:10}}>Baú de recompensa</h2></div><div className="fx2-chest"><div className="fx2-chest-glow"/><div className="fx2-chest-box"/></div><div className="fx2-title"><h2>Você concluiu sua ofensiva</h2><p>A recompensa existe porque houve comportamento real, não apenas abertura do app.</p></div><div className="fx2-rewards"><div className="fx2-reward"><Coins size={21} color="#426FF4"/><b>{ofensiva?.recompensa||0}</b><small>Cristais</small></div><div className="fx2-reward"><Star size={21} color="#F1A924"/><b>100</b><small>XP</small></div><div className="fx2-reward"><Gift size={21} color="#E0A127"/><b>Baú</b><small>Conquista</small></div></div><div style={{height:13}}/><button className="fx2-btn wide" onClick={abrirBau}>ABRIR E CONTINUAR</button></>;

  const Painel=()=> <><div className="fx2-title"><h2>Gráficos e categorias</h2><p>Entenda para evoluir.</p></div><Month/><div className="fx2-card">{categorias.length?<>{categorias.slice(0,7).map((c,i)=><div className="fx2-bar-row" key={c.nome}><span>{c.nome}</span><div className="fx2-bar"><i style={{width:`${c.pct}%`,background:COLORS[i%COLORS.length]}}/></div><b style={{fontSize:8,textAlign:'right'}}>{c.pct.toFixed(0)}%</b></div>)}</>:<Empty icon={PieChart} title="Sem despesas neste período" text="O ranking aparece quando houver gastos válidos no mês."/>}</div><Section title="Participação das despesas"><div className="fx2-card">{categorias.length?<div className="fx2-donut-wrap"><div className="fx2-donut" style={{background:`conic-gradient(${donutParts})`}}><strong><Money value={resumo.despesa} hidden={hidden}/></strong></div><div style={{flex:1}}>{categorias.slice(0,5).map((c,i)=><div className="fx2-legend" key={c.nome} style={{margin:'5px 0'}}><span><i style={{background:COLORS[i%COLORS.length]}}/>{c.nome}</span><span style={{marginLeft:'auto'}}>{c.pct.toFixed(0)}%</span></div>)}</div></div>:<Empty icon={PieChart} title="Nada para distribuir ainda" text="Nenhum dado fictício será mostrado."/>}</div></Section><Section title="Orçamentos" action="+ Novo" onAction={()=>abrir('orcamento',{categoria:'Total'})}><div className="fx2-list">{orcamentos.length?orcamentos.map(o=><div className="fx2-card" key={o.id}><div style={{display:'flex',justifyContent:'space-between'}}><b style={{fontSize:10}}>{o.categoria}</b><span className="fx2-muted">{Math.round(o.pct)}%</span></div><div style={{height:7}}/><Progress value={o.pct} tone={o.pct>100?'purple':''}/><div style={{display:'flex',justifyContent:'space-between',marginTop:7}}><span className="fx2-muted">Gasto <Money value={o.gasto} hidden={hidden}/></span><span className="fx2-muted">Limite <Money value={o.limite} hidden={hidden}/></span></div></div>):<div className="fx2-card"><Empty icon={Layers3} title="Sem orçamento definido" text="Você pode criar um limite total ou por categoria." action="CRIAR ORÇAMENTO" onAction={()=>abrir('orcamento',{categoria:'Total'})}/></div>}</div></Section>{projecao.baseadoEm>0&&<Section title="Próximo mês · projeção"><div className="fx2-card"><div className="fx2-grid2"><div><span className="fx2-label">Receitas recorrentes</span><span className="fx2-val"><Money value={projecao.receita} hidden={hidden}/></span></div><div><span className="fx2-label">Comprometido</span><span className="fx2-val"><Money value={projecao.comprometido} hidden={hidden}/></span></div></div><div style={{marginTop:11}}><span className="fx2-label">Livre projetado</span><span className="fx2-val"><Money value={projecao.livre} hidden={hidden}/></span></div><div className="fx2-muted" style={{marginTop:8}}>Estimativa baseada em recorrências, parcelas e compromissos cadastrados.</div></div></Section>}</>;

  const Reserva=()=> <><Back onClick={()=>setTela('mais')}/><div className="fx2-title"><h2>Reserva e investimentos</h2><p>Seu futuro começa agora.</p></div><div className="fx2-card" style={{textAlign:'center',paddingTop:20}}><div style={{width:178,height:178,borderRadius:'50%',margin:'0 auto 5px',padding:12,background:`conic-gradient(from 225deg,#246BFD 0deg ${pctMetaInvest*2.7}deg,#E9EDF5 ${pctMetaInvest*2.7}deg 270deg,transparent 270deg 360deg)`,display:'grid',placeItems:'center'}}><div style={{width:'100%',height:'100%',borderRadius:'50%',background:'#fff',display:'grid',placeItems:'center'}}><PiggyBank size={72} strokeWidth={1.7} color="#E5A09A"/></div></div><div className="fx2-bigmoney" style={{fontSize:26}}><Money value={totalInvestido} hidden={hidden}/></div><div className="fx2-muted" style={{fontWeight:800,color:fin.configuracao?.metaReserva>0?'#2BA954':undefined}}>{fin.configuracao?.metaReserva>0?`${Math.round(pctMetaInvest)}% da meta`:'Defina sua meta para acompanhar a evolução'}</div>{fin.configuracao?.metaReserva>0&&<div className="fx2-muted" style={{marginTop:4}}>Meta: <Money value={fin.configuracao.metaReserva} hidden={hidden}/>{fin.configuracao.prazoReserva?` até ${dateBr(fin.configuracao.prazoReserva)}`:''}</div>}<div style={{display:'grid',gridTemplateColumns:'repeat(3,1fr)',gap:8,marginTop:16}}><button className="fx2-btn ghost" style={{padding:'11px 5px',minHeight:73}} onClick={()=>abrir('investimento',{tipo:'Reserva',dataAtualizacao:hoje()})}><PiggyBank size={19} style={{display:'block',margin:'0 auto 5px'}}/><span style={{fontSize:9}}>Reserva</span><small style={{display:'block',fontSize:8,marginTop:3}}><Money value={reservaEmergencia} hidden={hidden}/></small></button><button className="fx2-btn ghost" style={{padding:'11px 5px',minHeight:73}} onClick={()=>abrir('investimento',{tipo:'CDB',dataAtualizacao:hoje()})}><TrendingUp size={19} style={{display:'block',margin:'0 auto 5px'}}/><span style={{fontSize:9}}>Aplicações</span><small style={{display:'block',fontSize:8,marginTop:3}}><Money value={aplicacoesTotal} hidden={hidden}/></small></button><button className="fx2-btn ghost" style={{padding:'11px 5px',minHeight:73}} onClick={()=>abrir('reserva',{metaReserva:fin.configuracao.metaReserva||'',prazoReserva:fin.configuracao.prazoReserva||'',aporteReservaMensal:fin.configuracao.aporteReservaMensal||''})}><Settings2 size={19} style={{display:'block',margin:'0 auto 5px'}}/><span style={{fontSize:9}}>Configurar</span><small style={{display:'block',fontSize:8,marginTop:3}}>Meta e prazo</small></button></div></div><Section title="Evolução da meta"><div className="fx2-card"><div style={{display:'flex',justifyContent:'flex-end',gap:5,marginBottom:10}}>{[[3,'3M'],[6,'6M'],[12,'12M'],[0,'Tudo']].map(([v,l])=><button key={l} onClick={()=>setInvestRange(v)} style={{border:'1px solid #E4E8F0',background:investRange===v?'#246BFD':'#fff',color:investRange===v?'#fff':'#6B7280',borderRadius:9,padding:'5px 8px',fontSize:8,fontWeight:800}}>{l}</button>)}</div>{evolucaoFiltrada.length>=2?<><div className="fx2-chart" style={{height:145}}><svg viewBox="0 0 100 100" preserveAspectRatio="none"><defs><linearGradient id="fx2InvestFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#246BFD" stopOpacity=".22"/><stop offset="100%" stopColor="#246BFD" stopOpacity="0"/></linearGradient></defs><polygon fill="url(#fx2InvestFill)" points={`0,100 ${investPoints} 100,100`}/><polyline fill="none" stroke="#246BFD" strokeWidth="2.2" vectorEffect="non-scaling-stroke" points={investPoints}/></svg></div><div className="fx2-legend" style={{justifyContent:'space-between'}}>{evolucaoFiltrada.map((x,i)=><span key={x.mes} style={{display:i===0||i===evolucaoFiltrada.length-1?'inline':'none'}}>{rotuloMes(x.mes)}</span>)}</div><div className="fx2-grid2" style={{marginTop:14}}><div><span className="fx2-label">Aportes no período</span><span className="fx2-val"><Money value={aportesPeriodo} hidden={hidden}/></span></div><div><span className="fx2-label">Média mensal</span><span className="fx2-val"><Money value={mediaAportes} hidden={hidden}/></span></div><div style={{gridColumn:'1 / -1'}}><span className="fx2-label">Evolução do patrimônio</span><span className={`fx2-val ${variacaoInvest>=0?'fx2-positive':'fx2-negative'}`}><Money value={variacaoInvest} hidden={hidden}/></span></div></div><div className="fx2-muted" style={{marginTop:9}}>Evolução patrimonial registrada. Aportes não são tratados como rentabilidade.</div></>:<Empty icon={TrendingUp} title="A evolução começa a partir das atualizações" text="Ao atualizar seus investimentos ao longo do tempo, a NIIL cria o histórico real da sua meta — sem inventar rentabilidade."/>}</div></Section><Section title="Patrimônio líquido"><div className="fx2-card"><div className="fx2-grid2"><div><span className="fx2-label">Liquidez</span><span className="fx2-val"><Money value={patri.liquidez} hidden={hidden}/></span></div><div><span className="fx2-label">Investimentos</span><span className="fx2-val"><Money value={patri.investimentos} hidden={hidden}/></span></div><div><span className="fx2-label">Dívidas</span><span className="fx2-val fx2-negative">- <Money value={patri.dividas} hidden={hidden}/></span></div><div><span className="fx2-label">Patrimônio líquido</span><span className="fx2-val"><Money value={patri.liquido} hidden={hidden}/></span></div></div></div></Section><Section title="Investimentos" action="+ Novo" onAction={()=>abrir('investimento',{tipo:'CDB',dataAtualizacao:hoje()})}>{fin.investimentos.length?<div className="fx2-list">{fin.investimentos.map(i=><div className="fx2-row click" key={i.id} onClick={()=>abrir('investimento',i)}><div className="fx2-row-icon">{String(i.tipo||'').toLowerCase()==='reserva'?<PiggyBank size={18}/>:<TrendingUp size={18}/>}</div><div className="fx2-row-main"><b>{i.nome}</b><small>{i.tipo}{i.dataAtualizacao?` · atualizado ${dateBr(i.dataAtualizacao)}`:''}</small></div><div className="fx2-row-value"><Money value={i.valorAtual} hidden={hidden}/></div></div>)}</div>:<div className="fx2-card"><Empty icon={TrendingUp} title="Nenhum investimento cadastrado" text="Cadastre sua reserva e suas aplicações para começar a acompanhar a meta."/></div>}</Section></>;

  const Objetivos=()=> <><div style={{display:'flex',justifyContent:'space-between',alignItems:'center'}}><div><h2 style={{fontSize:20,margin:'0 0 4px'}}>Objetivos</h2><div className="fx2-muted">Transforme valores em progresso.</div></div><button className="fx2-link" onClick={()=>abrir('objetivo',{prioridade:'Média',status:'ativo'})}>+ Novo</button></div><div className="fx2-section">{fin.objetivos.filter(o=>o.status!=='arquivado').length?fin.objetivos.filter(o=>o.status!=='arquivado').map(o=>{const p=progressoObjetivo(o,fin);return <div className="fx2-goal" key={o.id}><div style={{display:'flex',justifyContent:'space-between',gap:10}}><div><b style={{fontSize:12}}>{o.nome}</b><div className="fx2-muted">{o.prazo?`Prazo ${dateBr(o.prazo)}`:'Sem prazo definido'} · prioridade {o.prioridade||'Média'}</div></div><div className="fx2-ring" style={{background:`conic-gradient(#39B95B ${p.pct}%,#EDF0F4 0)`}}><span>{Math.round(p.pct)}%</span></div></div><div className="fx2-two" style={{margin:'12px 0 8px'}}><div><span className="fx2-label">Objetivo</span><span className="fx2-val"><Money value={p.alvo} hidden={hidden}/></span></div><div><span className="fx2-label">Já guardado</span><span className="fx2-val"><Money value={p.guardado} hidden={hidden}/></span></div></div><Progress value={p.pct}/><div style={{display:'flex',justifyContent:'space-between',marginTop:8}}><span className="fx2-muted">Faltam <Money value={p.faltam} hidden={hidden}/></span><button className="fx2-link" onClick={()=>abrir('objetivo',o)}>Editar</button></div></div>}):<div className="fx2-card"><Empty icon={Target} title="Crie seu primeiro objetivo" text="Casa, viagem, reserva ou qualquer meta importante." action="CRIAR OBJETIVO" onAction={()=>abrir('objetivo',{prioridade:'Média',status:'ativo'})}/></div>}</div></>;

  const Cartoes=()=> <><Back onClick={()=>setTela('mais')}/><div style={{display:'flex',justifyContent:'space-between',alignItems:'center'}}><div><h2 style={{fontSize:20,margin:'0 0 4px'}}>Cartões</h2><div className="fx2-muted">Faturas e limite comprometido.</div></div><button className="fx2-link" onClick={()=>abrir('cartao',{})}>+ Novo</button></div><div className="fx2-section">{fin.cartoes.length?fin.cartoes.map((c,i)=>{const fatura=gastoCartao(fin,c.id,mesRef),futuras=fin.transacoes.filter(t=>t.cartaoId===c.id&&t.tipo==='despesa'&&t.totalParcelas>t.parcelaAtual).reduce((a,t)=>a+Number(t.valor||0)*Math.max(0,Number(t.totalParcelas)-Number(t.parcelaAtual)),0),comp=fatura+futuras,lim=Number(c.limiteTotal||0),disp=Math.max(0,lim-comp),pct=lim?comp/lim*100:0;return <div className={`fx2-cardcredit ${i%2?'purple':''}`} key={c.id}><div style={{display:'flex',justifyContent:'space-between',alignItems:'center'}}><div><b style={{fontSize:11}}>{c.nome}</b><div className="fx2-muted">•••• {c.final||'----'} {c.bandeira?`· ${c.bandeira}`:''}</div></div><CreditCard size={25} color={i%2?'#8057E8':'#246BFD'}/></div><div className="fx2-two" style={{marginTop:12}}><div><span className="fx2-label">Fatura do mês</span><span className="fx2-val"><Money value={fatura} hidden={hidden}/></span></div><div><span className="fx2-label">Limite disponível estimado</span><span className="fx2-val">{lim?<Money value={disp} hidden={hidden}/>:'—'}</span></div><div><span className="fx2-label">Vencimento</span><span className="fx2-val">{c.vencimento?`dia ${c.vencimento}`:'—'}</span></div><div><span className="fx2-label">Limite total</span><span className="fx2-val">{lim?<Money value={lim} hidden={hidden}/>:'Não informado'}</span></div></div><div style={{marginTop:11}}><Progress value={pct} tone={i%2?'purple':'blue'}/></div><div className="fx2-muted" style={{marginTop:7}}>Estimativa considera a fatura e parcelas futuras cadastradas.</div></div>}):<div className="fx2-card"><Empty icon={CreditCard} title="Nenhum cartão cadastrado" text="Cadastre cartão, limite e vencimento. Compras vinculadas alimentarão a fatura." action="ADICIONAR CARTÃO" onAction={()=>abrir('cartao',{})}/></div>}</div></>;

  const Contas=()=> <><Back onClick={()=>setTela('mais')}/><div style={{display:'flex',justifyContent:'space-between'}}><div><h2 style={{fontSize:20,margin:'0 0 4px'}}>Contas</h2><div className="fx2-muted">Base do seu saldo disponível.</div></div><button className="fx2-link" onClick={()=>abrir('conta',{tipo:'Conta corrente',dataSaldo:hoje(),disponibilidadeImediata:true})}>+ Nova</button></div><div className="fx2-section">{fin.contas.length?<div className="fx2-list">{fin.contas.map(c=><div className="fx2-row click" key={c.id} onClick={()=>abrir('conta',c)}><div className="fx2-row-icon"><Landmark size={18}/></div><div className="fx2-row-main"><b>{c.nome}</b><small>{c.tipo} · {c.disponibilidadeImediata?'entra na liquidez':'fora da liquidez'} · {dateBr(c.dataSaldo)}</small></div><div className="fx2-row-value"><Money value={c.saldoAtual} hidden={hidden}/></div></div>)}</div>:<div className="fx2-card"><Empty icon={Landmark} title="Nenhuma conta cadastrada" text="Sem conta e saldo informado, a NIIL não mostra um saldo disponível fictício."/></div>}</div></>;
  const Dividas=()=> <><Back onClick={()=>setTela('mais')}/><div style={{display:'flex',justifyContent:'space-between'}}><div><h2 style={{fontSize:20,margin:'0 0 4px'}}>Dívidas e compromissos</h2><div className="fx2-muted">Saldo devedor não é despesa mensal.</div></div><button className="fx2-link" onClick={()=>abrir('divida',{tipo:'Financiamento'})}>+ Nova</button></div><div className="fx2-section">{fin.dividas.length?<div className="fx2-list">{fin.dividas.map(x=><div className="fx2-row click" key={x.id} onClick={()=>abrir('divida',x)}><div className="fx2-row-icon"><HandCoins size={18}/></div><div className="fx2-row-main"><b>{x.nome}</b><small>{x.tipo} · {x.parcelasRestantes||0} parcelas restantes{x.evolucaoObraMensal?` · evolução de obra ${formatoMoeda(x.evolucaoObraMensal,fin.configuracao?.moedaBase||'BRL')}`:''}</small></div><div className="fx2-row-value"><span className="fx2-label">Saldo</span><Money value={x.saldoDevedor} hidden={hidden}/></div></div>)}</div>:<div className="fx2-card"><Empty icon={HandCoins} title="Nenhuma dívida cadastrada" text="Financiamentos, consórcios e empréstimos podem ser acompanhados separadamente."/></div>}</div></>;
  const Movimentacoes=()=> <><Back onClick={()=>setTela('mais')}/><div style={{display:'flex',justifyContent:'space-between'}}><div><h2 style={{fontSize:20,margin:'0 0 4px'}}>Movimentações</h2><div className="fx2-muted">Histórico detalhado fica fora do painel principal.</div></div><button className="fx2-link" onClick={()=>abrir('transacao',{tipo:'despesa',natureza:'normal',data:hoje(),categoria:'Alimentação'})}>+ Nova</button></div><Month/><div className="fx2-list">{resumo.itens.length?resumo.itens.slice().sort((a,b)=>String(b.data).localeCompare(String(a.data))).map(t=>{const imp=impactos(t),neutro=imp.receita===0&&imp.despesa===0;return <div className="fx2-row" key={t.id}><div className="fx2-row-icon"><ReceiptText size={18}/></div><div className="fx2-row-main"><b>{t.descricaoOriginal}</b><small>{dateBr(t.data)} · {t.categoria}{neutro?' · movimentação patrimonial':''}{t.revisar?' · revisar':''}</small></div><div className={`fx2-row-value ${imp.receita>0?'fx2-positive':imp.despesa>0?'fx2-negative':''}`}>{neutro?'—':<Money value={t.valor} hidden={hidden}/>}</div></div>}):<div className="fx2-card"><Empty icon={ReceiptText} title="Sem movimentações neste mês" text="Adicione manualmente ou importe seus documentos."/></div>}</div></>;
  const Revisoes=()=> <><Back onClick={()=>setTela('mais')}/><div className="fx2-title"><h2>Revisões da NIIL</h2><p>Nada duvidoso entra silenciosamente como verdade.</p></div>{pendentes.length?<div className="fx2-list">{pendentes.map(t=><div className="fx2-row click" key={t.id} onClick={()=>abrir('revisarTx',{...t,termoRegra:t.descricaoOriginal,criarRegra:false})}><div className="fx2-row-icon"><ListChecks size={18}/></div><div className="fx2-row-main"><b>{t.descricaoOriginal}</b><small>Sugestão: {t.categoria} · confiança {Math.round((t.confiancaClassificacao||0)*100)}%</small></div><div className="fx2-row-value"><Money value={t.valor} hidden={hidden}/></div></div>)}</div>:<div className="fx2-card"><Empty icon={Check} title="Tudo revisado" text="Não há classificações pendentes."/></div>}</>;

  const Importar=()=> <><Back onClick={()=>setTela('mais')}/><div className="fx2-title"><h2>Adicionar dados</h2><p>CSV é processado localmente. PDF e imagem passam pela leitura inteligente e itens ambíguos vão para revisão.</p></div><Field label="Vincular a uma conta"><select value={contaImport} onChange={e=>setContaImport(e.target.value)}><option value="">Sem conta definida</option>{fin.contas.map(c=><option key={c.id} value={c.id}>{c.nome}</option>)}</select></Field><div className="fx2-file"><input ref={inputFile} id="fx2-file" type="file" accept=".csv,application/pdf,image/*" onChange={e=>importarArquivo(e.target.files?.[0])}/><label htmlFor="fx2-file"><FileUp size={30} color="#246BFD"/><b>{importando?'Processando…':'Selecionar CSV, PDF ou imagem'}</b><small>O arquivo não é mostrado no painel; apenas os dados organizados alimentam o sistema.</small></label></div>{importResult&&<div className="fx2-card" style={{marginTop:12}}><b style={{fontSize:11}}>{importResult.arquivo}</b><div className="fx2-two" style={{marginTop:10}}><div><span className="fx2-label">Importados</span><span className="fx2-val">{importResult.inseridas}</span></div><div><span className="fx2-label">Duplicados bloqueados</span><span className="fx2-val">{importResult.duplicadas}</span></div></div>{importResult.revisar>0&&<div className="fx2-alert" style={{marginTop:10}}>{importResult.revisar} itens foram enviados para revisão.</div>}{(importResult.perguntas||[]).map((p,i)=><div className="fx2-review" key={i}><b>Precisamos confirmar</b><small>{p}</small></div>)}</div>}<Section title="Importações anteriores">{fin.importacoes.length?<div className="fx2-list">{fin.importacoes.slice().reverse().slice(0,10).map(i=><div className="fx2-row" key={i.id}><div className="fx2-row-icon"><FolderClock size={18}/></div><div className="fx2-row-main"><b>{i.arquivo}</b><small>{dateBr(i.data)} · {i.inseridas} inseridos · {i.duplicadas} duplicados</small></div></div>)}</div>:<div className="fx2-card"><Empty icon={FolderClock} title="Nenhuma importação ainda" text="O histórico de importações ajuda a evitar duplicidades."/></div>}</Section></>;
  const Mais=()=> <><div className="fx2-card" style={{background:'linear-gradient(145deg,#F2F7FF,#FBFCFF)',borderColor:'#DFE8FF'}}><div style={{display:'flex',gap:12,alignItems:'center'}}><div className="fx2-brandmark"><WalletCards size={21}/></div><div><b style={{fontSize:12}}>Seu financeiro, todo conectado</b><div className="fx2-muted">Uma alteração na base recalcula painel, metas, gráficos e trilha.</div></div></div></div><div className="fx2-section fx2-more-grid">{[['contas','Contas','Saldos e liquidez',Landmark],['cartoes','Cartões','Faturas e limites',CreditCard],['reserva','Investimentos','Reserva e patrimônio',TrendingUp],['dividas','Dívidas','Financiamentos e consórcios',HandCoins],['movimentacoes','Movimentações','Histórico detalhado',ReceiptText],['importar','Importações','CSV, PDF e imagem',Upload],['revisoes','Revisões',`${pendentes.length} pendentes`,ListChecks],['painel','Orçamentos','Limites e projeções',Layers3]].map(([id,n,s,Icon])=><div className="fx2-more-card" key={id} onClick={()=>setTela(id)}><Icon size={20}/><b>{n}</b><small>{s}</small></div>)}</div><Section title="Privacidade"><div className="fx2-security"><div className="fx2-card"><ShieldCheck size={18} color="#31B65A"/><b>Painel agregado</b><small>Seu extrato não fica exposto na tela principal.</small></div><div className="fx2-card"><LockKeyhole size={18} color="#246BFD"/><b>Ocultar valores</b><small>Use o olho no painel quando precisar de privacidade.</small></div></div></Section></>;

  const render=()=>{if(tela==='trilha')return Trilha();if(tela==='ofensiva')return Ofensiva();if(tela==='bau')return Bau();if(tela==='painel')return Painel();if(tela==='reserva')return Reserva();if(tela==='objetivos')return Objetivos();if(tela==='cartoes')return Cartoes();if(tela==='contas')return Contas();if(tela==='dividas')return Dividas();if(tela==='movimentacoes')return Movimentacoes();if(tela==='revisoes')return Revisoes();if(tela==='importar')return Importar();if(tela==='mais')return Mais();return Visao()};

  const Modal=()=>{
    if(!modal)return null;const m=modal.data||{};const input=(key,props={})=><input {...props} value={m[key]??''} onChange={e=>atualizarModal({[key]:e.target.value})}/>;
    if(modal.tipo==='transacao')return <Sheet title="Novo lançamento" onClose={fechar}><div className="fx2-toggle"><button className={m.tipo==='despesa'?'active':''} onClick={()=>atualizarModal({tipo:'despesa',categoria:'Alimentação'})}>Despesa</button><button className={m.tipo==='receita'?'active':''} onClick={()=>atualizarModal({tipo:'receita',categoria:'Salário'})}>Receita</button></div><Field label="Natureza"><select value={m.natureza||'normal'} onChange={e=>atualizarModal({natureza:e.target.value})}><option value="normal">Receita / despesa normal</option><option value="transferencia">Transferência entre contas próprias</option><option value="fatura">Pagamento de fatura</option><option value="aporte">Aporte em investimento</option><option value="resgate">Resgate de investimento</option><option value="estorno">Estorno / reembolso de despesa</option></select></Field><div className="fx2-two"><Field label="Data">{input('data',{type:'date'})}</Field><Field label="Valor">{input('valor',{inputMode:'decimal',placeholder:'0,00'})}</Field></div><Field label="Descrição">{input('descricaoOriginal',{placeholder:'Ex.: supermercado, salário...'})}</Field><Field label="Categoria"><select value={m.categoria||'Outros'} onChange={e=>atualizarModal({categoria:e.target.value})}>{(m.tipo==='receita'?CATEGORIAS_RECEITA:CATEGORIAS_DESPESA).map(c=><option key={c}>{c}</option>)}</select></Field><div className="fx2-two"><Field label="Conta"><select value={m.contaId||''} onChange={e=>atualizarModal({contaId:e.target.value})}><option value="">Sem conta</option>{fin.contas.map(c=><option value={c.id} key={c.id}>{c.nome}</option>)}</select></Field><Field label="Cartão"><select value={m.cartaoId||''} onChange={e=>atualizarModal({cartaoId:e.target.value})}><option value="">Sem cartão</option>{fin.cartoes.map(c=><option value={c.id} key={c.id}>{c.nome}</option>)}</select></Field></div><div className="fx2-two"><Field label="Parcela atual">{input('parcelaAtual',{type:'number',min:0})}</Field><Field label="Total parcelas">{input('totalParcelas',{type:'number',min:0})}</Field></div><label style={{display:'flex',gap:8,alignItems:'center',fontSize:10,margin:'4px 0 13px'}}><input type="checkbox" checked={!!m.recorrente} onChange={e=>atualizarModal({recorrente:e.target.checked})}/> Movimentação recorrente</label><button className="fx2-btn wide" onClick={salvarTransacao}><Save size={14} style={{verticalAlign:'middle'}}/> SALVAR</button></Sheet>;
    if(modal.tipo==='conta')return <Sheet title={m.id?'Editar conta':'Nova conta'} onClose={fechar}><Field label="Nome">{input('nome',{placeholder:'Ex.: Inter Pessoal'})}</Field><Field label="Instituição">{input('instituicao',{placeholder:'Banco ou instituição'})}</Field><Field label="Tipo"><select value={m.tipo||'Conta corrente'} onChange={e=>atualizarModal({tipo:e.target.value})}>{TIPOS_CONTA.map(x=><option key={x}>{x}</option>)}</select></Field><div className="fx2-two"><Field label="Saldo atual">{input('saldoAtual',{inputMode:'decimal'})}</Field><Field label="Data do saldo">{input('dataSaldo',{type:'date'})}</Field></div><label style={{display:'flex',gap:8,alignItems:'center',fontSize:10,margin:'4px 0 13px'}}><input type="checkbox" checked={m.disponibilidadeImediata!==false} onChange={e=>atualizarModal({disponibilidadeImediata:e.target.checked})}/> Disponibilidade imediata</label><button className="fx2-btn wide" onClick={salvarConta}>SALVAR CONTA</button></Sheet>;
    if(modal.tipo==='cartao')return <Sheet title={m.id?'Editar cartão':'Novo cartão'} onClose={fechar}><Field label="Nome">{input('nome',{placeholder:'Ex.: Cartão Inter'})}</Field><div className="fx2-two"><Field label="Bandeira">{input('bandeira',{placeholder:'Visa'})}</Field><Field label="Final">{input('final',{maxLength:4,inputMode:'numeric'})}</Field></div><Field label="Limite total">{input('limiteTotal',{inputMode:'decimal'})}</Field><div className="fx2-two"><Field label="Fechamento (dia)">{input('fechamento',{type:'number',min:1,max:31})}</Field><Field label="Vencimento (dia)">{input('vencimento',{type:'number',min:1,max:31})}</Field></div><Field label="Conta de pagamento"><select value={m.contaPagamentoId||''} onChange={e=>atualizarModal({contaPagamentoId:e.target.value})}><option value="">Não definida</option>{fin.contas.map(c=><option value={c.id} key={c.id}>{c.nome}</option>)}</select></Field><button className="fx2-btn wide" onClick={salvarCartao}>SALVAR CARTÃO</button></Sheet>;
    if(modal.tipo==='investimento')return <Sheet title={m.id?'Editar investimento':'Novo investimento'} onClose={fechar}><Field label="Nome">{input('nome',{placeholder:'Ex.: CDB Inter'})}</Field><div className="fx2-two"><Field label="Tipo"><select value={m.tipo||'CDB'} onChange={e=>atualizarModal({tipo:e.target.value})}>{TIPOS_INVESTIMENTO.map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Instituição">{input('instituicao')}</Field></div><div className="fx2-two"><Field label="Valor aplicado">{input('valorAplicado',{inputMode:'decimal'})}</Field><Field label="Valor atual">{input('valorAtual',{inputMode:'decimal'})}</Field></div><div className="fx2-two"><Field label="Liquidez">{input('liquidez',{placeholder:'Diária, D+1...'})}</Field><Field label="Atualizado em">{input('dataAtualizacao',{type:'date'})}</Field></div><Field label="Vincular a objetivo"><select value={m.objetivoId||''} onChange={e=>atualizarModal({objetivoId:e.target.value})}><option value="">Nenhum</option>{fin.objetivos.filter(o=>o.status!=='arquivado').map(o=><option value={o.id} key={o.id}>{o.nome}</option>)}</select></Field><button className="fx2-btn wide" onClick={salvarInvestimento}>SALVAR INVESTIMENTO</button></Sheet>;
    if(modal.tipo==='divida')return <Sheet title={m.id?'Editar dívida':'Nova dívida'} onClose={fechar}><Field label="Nome">{input('nome',{placeholder:'Ex.: Financiamento do imóvel'})}</Field><Field label="Tipo"><select value={m.tipo||'Financiamento'} onChange={e=>atualizarModal({tipo:e.target.value})}>{TIPOS_DIVIDA.map(x=><option key={x}>{x}</option>)}</select></Field><div className="fx2-two"><Field label="Valor original">{input('valorOriginal',{inputMode:'decimal'})}</Field><Field label="Saldo devedor">{input('saldoDevedor',{inputMode:'decimal'})}</Field></div><div className="fx2-two"><Field label="Valor parcela">{input('valorParcela',{inputMode:'decimal'})}</Field><Field label="Parcelas restantes">{input('parcelasRestantes',{type:'number',min:0})}</Field></div><div className="fx2-two"><Field label="Amortização/mês">{input('amortizacaoMensal',{inputMode:'decimal'})}</Field><Field label="Juros/mês">{input('jurosMensal',{inputMode:'decimal'})}</Field><Field label="Evolução de obra/mês">{input('evolucaoObraMensal',{inputMode:'decimal'})}</Field><Field label="Seguro/mês">{input('seguroMensal',{inputMode:'decimal'})}</Field><Field label="Taxas/mês">{input('taxasMensais',{inputMode:'decimal'})}</Field><Field label="Outros que não amortizam">{input('outrosNaoAmortizamMensal',{inputMode:'decimal'})}</Field></div><div className="fx2-muted" style={{margin:'2px 0 10px'}}>Apenas a amortização reduz o saldo principal. Evolução de obra, juros, seguros e taxas entram no comprometimento, mas não como redução da dívida.</div><div className="fx2-two"><Field label="Taxa % (opcional)">{input('taxa',{inputMode:'decimal'})}</Field><Field label="Vencimento (dia)">{input('vencimento',{type:'number',min:1,max:31})}</Field></div><button className="fx2-btn wide" onClick={salvarDivida}>SALVAR</button></Sheet>;
    if(modal.tipo==='objetivo')return <Sheet title={m.id?'Editar objetivo':'Novo objetivo'} onClose={fechar}><Field label="Nome">{input('nome',{placeholder:'Ex.: Casa nova'})}</Field><div className="fx2-two"><Field label="Valor alvo">{input('valorAlvo',{inputMode:'decimal'})}</Field><Field label="Já guardado">{input('valorGuardado',{inputMode:'decimal'})}</Field></div><Field label="Prazo">{input('prazo',{type:'date'})}</Field><div className="fx2-two"><Field label="Prioridade"><select value={m.prioridade||'Média'} onChange={e=>atualizarModal({prioridade:e.target.value})}><option>Alta</option><option>Média</option><option>Baixa</option></select></Field><Field label="Status"><select value={m.status||'ativo'} onChange={e=>atualizarModal({status:e.target.value})}><option value="ativo">Ativo</option><option value="concluido">Concluído</option><option value="arquivado">Arquivado</option></select></Field></div><button className="fx2-btn wide" onClick={salvarObjetivo}>SALVAR OBJETIVO</button></Sheet>;
    if(modal.tipo==='orcamento')return <Sheet title={m.id?'Editar orçamento':'Novo orçamento'} onClose={fechar}><Field label="Categoria"><select value={m.categoria||'Total'} onChange={e=>atualizarModal({categoria:e.target.value})}><option>Total</option>{CATEGORIAS_DESPESA.map(c=><option key={c}>{c}</option>)}</select></Field><Field label="Limite mensal">{input('limite',{inputMode:'decimal',placeholder:'0,00'})}</Field><button className="fx2-btn wide" onClick={salvarOrcamento}>SALVAR LIMITE</button></Sheet>;
    if(modal.tipo==='reserva')return <Sheet title="Meta de investimentos" onClose={fechar}><Field label="Valor alvo">{input('metaReserva',{inputMode:'decimal'})}</Field><Field label="Prazo">{input('prazoReserva',{type:'date'})}</Field><Field label="Aporte mensal desejado (opcional)">{input('aporteReservaMensal',{inputMode:'decimal'})}</Field><div className="fx2-muted" style={{marginBottom:12}}>A meta considera Reserva de emergência + Aplicações cadastradas.</div><button className="fx2-btn wide" onClick={salvarReserva}>ATUALIZAR META</button></Sheet>;
    if(modal.tipo==='revisarTx')return <Sheet title="Revisar classificação" onClose={fechar}><div className="fx2-card" style={{marginBottom:11}}><b style={{fontSize:11}}>{m.descricaoOriginal}</b><div className="fx2-muted"><Money value={m.valor} hidden={hidden}/> · {dateBr(m.data)}</div></div><Field label="Categoria"><select value={m.categoria||'Outros'} onChange={e=>atualizarModal({categoria:e.target.value})}>{(m.tipo==='receita'?CATEGORIAS_RECEITA:CATEGORIAS_DESPESA).map(c=><option key={c}>{c}</option>)}</select></Field><label style={{display:'flex',gap:8,alignItems:'center',fontSize:10,margin:'5px 0 9px'}}><input type="checkbox" checked={!!m.criarRegra} onChange={e=>atualizarModal({criarRegra:e.target.checked})}/> Usar esta correção em descrições semelhantes</label>{m.criarRegra&&<Field label="Termo da regra">{input('termoRegra',{placeholder:'Ex.: NOME DO ESTABELECIMENTO'})}</Field>}<button className="fx2-btn wide" onClick={revisarTx}>CONFIRMAR</button></Sheet>;
    return null;
  };

  return <CurrencyContext.Provider value={fin.configuracao?.moedaBase||'BRL'}><div className="fx2"><div className="fx2-shell"><Header/>{render()}</div><Modal/></div></CurrencyContext.Provider>;
}
